 "content": "def transform(grid):
    """Count T tetrominoes by stem direction, packing each class into a 2x2 panel."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 1: 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            if len(cells) != 4:
                continue
            row_counts = {}
            for y, _ in cells:
                row_counts[y] = row_counts.get(y, 0) + 1
            bars = [y for y, n in row_counts.items() if n == 3]
            stems = [y for y, n in row_counts.items() if n == 1]
            if len(bars) == 1 and len(stems) == 1:
                # Stem above bar is color 3; stem below bar is color 1.
                color = 3 if stems[0] < bars[0] else 1
                counts[color] += 1
    out = [[0] * 6 for _ in range(3)]
    # Each color has a 2x2 panel; fill column-major in the available corner cells.
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for color, offset in ((3, 0), (1, 3)):
        for i in range(min(counts[color], 4)):
            r, c = slots[i]
            out[r][c + offset] = color
    return out
"
